LoginResponse res = authService.login(request);
if (Boolean.TRUE.equals(res.getSuccess())) {
    return ResponseEntity.ok(res);
}
return ResponseEntity.badRequest().body(res);

var payment=db.one("SELECT * FROM public.payments WHERE id=?",id);
orders.owned(uuid(payment.get("order_id")),actors.get(),false);
return payment;

if(!Set.of("SUCCESS","FAILED").contains(result))throw new BadRequestException("INVALID_PAYMENT_RESULT");
var payment=detail(id);UUID order=uuid(payment.get("order_id"));var amount=money(payment.get("amount"));
return payments.callback(new CommerceRequests.Callback(id,order,amount,result,payments.sign(id,order,amount,result)));

reports.definition(code);var report=reports.data(request.params());
String extension="PDF".equals(request.format())?"pdf":"xlsx";
String filename=code+"_"+report.from().format(DateTimeFormatter.BASIC_ISO_DATE)+"_"+report.to().format(DateTimeFormatter.BASIC_ISO_DATE)+"."+extension;
return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+filename+"\"")
    .contentType(MediaType.parseMediaType("PDF".equals(request.format())?"application/pdf":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
    .body(reports.export(report,request.format()));
